function gridRescueHops(grid) {
    const rows = grid.length;
    const cols = grid[0].length;
    const distance = grid.map((row) => row.split("").map(() => Infinity));
    let target = null;
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] === "S")
                distance[r][c] = 0;
            if (grid[r][c] === "T")
                target = [r, c];
        }
    }
    let changed = true;
    while (changed) {
        changed = false;
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                if (grid[r][c] === "#")
                    continue;
                for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
                    const nr = r + dr;
                    const nc = c + dc;
                    if (nr < 0 || nc < 0 || nr >= rows || nc >= cols)
                        continue;
                    if (distance[nr][nc] + 1 < distance[r][c]) {
                        distance[r][c] = distance[nr][nc] + 1;
                        changed = true;
                    }
                }
            }
        }
    }
    const best = distance[target[0]][target[1]];
    return best === Infinity ? -1 : best;
}

function gridRescueHops(grid) {
    const rows = grid.length;
    const cols = grid[0].length;
    let start = 0;
    for (let r = 0; r < rows; r++) {
        const c = grid[r].indexOf("S");
        if (c >= 0)
            start = r * cols + c;
    }
    const distance = new Map([[start, 0]]);
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
        const cell = queue[head];
        const r = Math.floor(cell / cols);
        const c = cell % cols;
        if (grid[r][c] === "T")
            return distance.get(cell);
        for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || grid[nr][nc] === "#")
                continue;
            const next = nr * cols + nc;
            if (!distance.has(next)) {
                distance.set(next, distance.get(cell) + 1);
                queue.push(next);
            }
        }
    }
    return -1;
}
